const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const reykjavik = ee.Geometry.Point([-21.9426, 64.147]); // A point in central Reykjavík
  const snaefellsnes = ee.Geometry.Point([-23.5, 64.9]); // A point on Snæfellsnes peninsula, less populated area
  const year = 2016;
  const startDate = ee.Date.fromYMD(year, 1, 1);
  const endDate = ee.Date.fromYMD(year, 12, 31);
  const scale = 1000; // 1 km scale for reduction

  // 2. Data Acquisition
  let dnbCollection = ee.ImageCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSL')
    .filterDate(startDate, endDate)
    .select('avg_rad'); // Average radiance

  // Check if collection is empty for Reykjavík's area. Filtering by geometry later to avoid large initial filters.
  const allImagesInCollection = dnbCollection.filterBounds(reykjavik).size().getInfo();
  if (allImagesInCollection === 0) {
    console.log(`C1: No VIIRS DNB images found for ${year} near Reykjavík.`);
    console.log("C1");
    return;
  }

  // Create a composite image for the year
  const annualComposite = dnbCollection.mean();

  // 3. Processing & Calculation
  // Reduce regions to get mean 'avg_rad' values
  const reykjavikStats = annualComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: reykjavik,
    scale: scale,
    maxPixels: 1e9
  });

  const snaefellsnesStats = annualComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: snaefellsnes,
    scale: scale,
    maxPixels: 1e9
  });

  const reykjavikNtl = reykjavikStats.get('avg_rad').getInfo();
  const snaefellsnesNtl = snaefellsnesStats.get('avg_rad').getInfo();

  // Validate results
  if (reykjavikNtl === null || snaefellsnesNtl === null ||
      isNaN(reykjavikNtl) || isNaN(snaefellsnesNtl)) {
    console.log("C3: Calculation failed, one or both NTL values are null/NaN.");
    console.log("C3");
    return;
  }

  // To check for C2 (No valid pixels), we can use a reducer that counts valid pixels.
  // For 'mean', if no pixels, it usually returns null, which is caught by C3.
  // If mean is 0, it means valid pixels had 0 values.
  const reykjavikPixelCount = annualComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: reykjavik,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  const snaefellsnesPixelCount = annualComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: snaefellsnes,
    scale: scale,
    maxPixels: 1e9
  }).get('avg_rad').getInfo();

  if (reykjavikPixelCount === 0 || snaefellsnesPixelCount === 0) {
    console.log(`C2: No valid pixels for one or both locations after processing. Reykjavik Pixels: ${reykjavikPixelCount}, Snaefellsnes Pixels: ${snaefellsnesPixelCount}`);
    console.log("C2");
    return;
  }

  // 4. Comparison and Final Answer
  console.log(`Reykjavík NTL (avg_rad): ${reykjavikNtl.toFixed(4)} (Pixels: ${reykjavikPixelCount})`);
  console.log(`Snæfellsnes NTL (avg_rad): ${snaefellsnesNtl.toFixed(4)} (Pixels: ${snaefellsnesPixelCount})`);

  if (reykjavikNtl > snaefellsnesNtl) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
